/ ------------------------------------------------------------\n  always_comb begin\n    next_state   = state;\n    init_assign  = 1'b0;\n    inc_assign   = 1'b0;\n    clear_sums   = 1'b0;\n\n    case (state)\n      IDLE: begin\n        if (start) begin\n          next_state  = INIT;\n        end\n      end\n\n      INIT: begin\n        // initialize assignment counter and sums\n        init_assign = 1'b1;\n        clear_sums  = 1'b1;\n        next_state  = COMPUTE_SUMS;\n      end\n\n      COMPUTE_SUMS: begin\n        if (compute_done) begin\n          next_state = PRIME_LOOKUP;\n        end\n      end\n\n      PRIME_LOOKUP: begin\n        if (prime_lookup_done) begin\n          next_state = UPDATE_MAX;\n        end\n      end\n\n      UPDATE_MAX: begin\n        // After updating max, move to next assignment or finish\n        if (last_assignment) begin\n          next_state = DONE;\n        end else begin\n          // increment assignment pattern and recompute sums\n          inc_assign = 1'b1;\n          clear_sums = 1'b1;\n          next_state = COMPUTE_SUMS;\n        end\n      end\n\n      DONE: begin\n        // stay in DONE until start goes low then high again\n        if (!start)\n          next_state = IDLE;\n      end\n\n      default: begin\n        next_state = IDLE;\n      end\n    endcase\n  end\n\n  // ------------------------------------------------------------\n  // FSM state register and done signal\n  // ------------------------------------------------------------\n  always_ff @(posedge clk or negedge rst_n) begin\n    if (!rst_n)\n      state <= IDLE;\n    else\n      state <= next_state;\n  end\n\n  always_ff @(posedge clk or negedge rst_n) begin\n    if (!rst_n)\n      done <= 1'b0;\n    else\n      done <= (state == DONE);\n  end\n\nendmodule"}\n```